"use client";

import { useEffect, useId, useState } from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { CalendarIcon, MaximizeIcon, PlusIcon } from "../parts/icons";
import { MinusIcon } from "./icons";
import { EVENT, HOLD_SECONDS, MAX_SEATS, type Seat, SEATS, type TierId } from "./seat-map/data";
import { HallMap } from "./seat-map/hall-map";
import { SeatLegend } from "./seat-map/seat-legend";
import { SeatSummary } from "./seat-map/seat-summary";
import { TierChips } from "./seat-map/tier-chips";
import { MAX_ZOOM, useCamera, WHOLE_HALL } from "./seat-map/use-camera";

// The map's tab stop starts on the open seat nearest the middle of the front row.
const FIRST_FOCUS =
  SEATS.filter((seat) => seat.row === 0 && seat.status === "open").toSorted((a, b) => Math.abs(a.angle) - Math.abs(b.angle))[0]?.id ??
  SEATS[0]!.id;

/**
 * A seat picker for a clinic workshop: pick a price tier to fly to its seats,
 * zoom and drag the hall, choose up to six seats by pointer or keyboard, and
 * book them before the ten minute hold runs out.
 */
export function SeatMap({ className }: { className?: string }) {
  const titleId = useId();
  const camera = useCamera();
  const [seats, setSeats] = useState(SEATS);
  const [chosen, setChosen] = useState<string[]>([]);
  const [focusId, setFocusId] = useState(FIRST_FOCUS);
  const [activeTier, setActiveTier] = useState<TierId | null>(null);
  const [holdEnds, setHoldEnds] = useState<number | null>(null);
  const [now, setNow] = useState(0);
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (holdEnds === null) return;
    const tick = setInterval(() => {
      const time = Date.now();
      if (time >= holdEnds) {
        setChosen([]);
        setHoldEnds(null);
        setMessage("Your hold ran out, so the seats went back on sale.");
      } else setNow(time);
    }, 1000);
    return () => clearInterval(tick);
  }, [holdEnds]);

  const chosenSet = new Set(chosen);
  const chosenSeats = chosen.map((id) => seats.find((seat) => seat.id === id)).filter((seat): seat is Seat => seat !== undefined);
  const secondsLeft = holdEnds === null ? null : Math.max(0, Math.ceil((holdEnds - now) / 1000));

  const setSelection = (next: string[]) => {
    setChosen(next);
    if (next.length === 0) setHoldEnds(null);
    else if (holdEnds === null) {
      const time = Date.now();
      setNow(time);
      setHoldEnds(time + HOLD_SECONDS * 1000);
    }
  };

  const toggle = (seat: Seat) => {
    if (seat.status !== "open") {
      setMessage(`Row ${seat.rowName}, seat ${seat.number} is ${seat.status === "sold" ? "sold" : "on hold for someone else"}.`);
      return;
    }
    if (chosenSet.has(seat.id)) {
      setSelection(chosen.filter((id) => id !== seat.id));
      setMessage(`Let go of row ${seat.rowName}, seat ${seat.number}.`);
    } else if (chosen.length >= MAX_SEATS) {
      setMessage("One booking can hold up to six seats.");
    } else {
      setSelection([...chosen, seat.id]);
      setMessage(`Chose row ${seat.rowName}, seat ${seat.number}.`);
    }
  };

  const follow = (seat: Seat) => {
    setFocusId(seat.id);
    const look = camera.read();
    if (look.zoom <= 1.01) return;
    const halfWidth = 380 / look.zoom;
    const halfHeight = 230 / look.zoom;
    if (Math.abs(seat.x - look.x) > halfWidth * 0.6 || Math.abs(seat.y - look.y) > halfHeight * 0.6) {
      camera.flyTo({ x: seat.x, y: seat.y, zoom: look.zoom });
    }
  };

  const chooseTier = (tier: TierId | null) => {
    setActiveTier(tier);
    if (tier === null) {
      camera.flyTo(WHOLE_HALL);
      return;
    }
    const group = seats.filter((seat) => seat.tier === tier);
    const xs = group.map((seat) => seat.x);
    const ys = group.map((seat) => seat.y);
    const [left, right, top, bottom] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
    // Fit the tier with a margin, but never so close that the seats around it drop out of view.
    const zoom = Math.min(2.2, 760 / (right - left + 80), 460 / (bottom - top + 80));
    camera.flyTo({ x: (left + right) / 2, y: (top + bottom) / 2, zoom });
  };

  const zoomBy = (factor: number) => {
    const look = camera.read();
    camera.flyTo({ x: look.x, y: look.y, zoom: camera.zoom * factor });
  };

  const book = () => {
    const count = chosen.length;
    setSeats((current) => current.map((seat) => (chosenSet.has(seat.id) ? { ...seat, status: "sold" } : seat)));
    setSelection([]);
    setMessage(`Booked ${count} ${count === 1 ? "seat" : "seats"}. The tickets are on their way to your inbox.`);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex items-center gap-3 border-b border-border px-5 py-4">
        <span aria-hidden="true" className="grid size-11 shrink-0 place-items-center rounded-xl bg-chart-1/15 text-chart-1">
          <CalendarIcon className="size-5" />
        </span>
        <div className="min-w-0">
          <h2 id={titleId} className="truncate text-base font-semibold">
            {EVENT.title}
          </h2>
          <p className="text-sm text-muted-foreground">
            {EVENT.when}, {EVENT.venue}
          </p>
        </div>
      </header>

      <TierChips seats={seats} chosen={chosenSet} active={activeTier} onChange={chooseTier} />

      <div className="grid @3xl:grid-cols-[1fr_19rem]">
        <div className="flex min-w-0 flex-col gap-3 border-t border-border p-4">
          <div className="relative overflow-hidden rounded-xl border border-border">
            <HallMap
              seats={seats}
              chosen={chosenSet}
              focusId={focusId}
              onFocusSeat={follow}
              onToggle={toggle}
              activeTier={activeTier}
              camera={camera}
            />
            <div role="group" aria-label="Zoom" className="absolute right-2 bottom-2 flex flex-col gap-1">
              <Button type="button" variant="outline" size="icon" aria-label="Zoom in" disabled={camera.zoom >= MAX_ZOOM} onClick={() => zoomBy(1.6)} className="size-8">
                <PlusIcon aria-hidden="true" className="size-4" />
              </Button>
              <Button type="button" variant="outline" size="icon" aria-label="Zoom out" disabled={camera.zoom <= 1} onClick={() => zoomBy(1 / 1.6)} className="size-8">
                <MinusIcon aria-hidden="true" className="size-4" />
              </Button>
              <Button
                type="button"
                variant="outline"
                size="icon"
                aria-label="Show the whole hall"
                onClick={() => {
                  setActiveTier(null);
                  camera.flyTo(WHOLE_HALL);
                }}
                className="size-8"
              >
                <MaximizeIcon aria-hidden="true" className="size-4" />
              </Button>
            </div>
          </div>
          <SeatLegend />
        </div>
        <div className="border-t border-border p-4 @3xl:border-l">
          <SeatSummary
            seats={chosenSeats}
            secondsLeft={secondsLeft}
            message={message}
            onRemove={toggle}
            onBook={book}
          />
        </div>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

