import { seededRandom } from "../../lib/plot";

/** The price tiers of the hall. */
export type TierId = "front" | "middle" | "upper" | "side";

/** One price tier: its name, price and the chart colour its seats take. */
export interface Tier {
  id: TierId;
  name: string;
  price: number;
  /** Fill class for the tier's open seats. */
  fill: string;
  /** Background class for the tier's chip marker. */
  dot: string;
}

/** The tiers in chip order. */
export const TIERS: Tier[] = [
  { id: "front", name: "Front", price: 48, fill: "fill-chart-1", dot: "bg-chart-1" },
  { id: "middle", name: "Middle", price: 36, fill: "fill-chart-2", dot: "bg-chart-2" },
  { id: "side", name: "Side", price: 24, fill: "fill-chart-3", dot: "bg-chart-3" },
  { id: "upper", name: "Upper", price: 18, fill: "fill-chart-4", dot: "bg-chart-4" },
];

/** Whether a seat can be picked. */
export type SeatStatus = "open" | "held" | "sold";

/** The three blocks of seats, split by the aisles. */
export type Section = "left" | "centre" | "right";

/** One seat on the map, placed in the map's own units. */
export interface Seat {
  id: string;
  /** The row's place from the stage, from 0. */
  row: number;
  /** The row's letter, such as C. */
  rowName: string;
  /** The seat's number in its row, counted from the left. */
  number: number;
  section: Section;
  tier: TierId;
  status: SeatStatus;
  /** A space kept for a wheelchair, with no fixed seat. */
  wheelchair: boolean;
  x: number;
  y: number;
  /** The seat's angle from the hall's centre line, in radians. Arrow keys use it to find the seat in front or behind. */
  angle: number;
}

/** The event the seats are for. */
export const EVENT = {
  title: "Steady hands: a suturing workshop",
  when: "Sat Nov 21, 10:00 am",
  venue: "Calder Lecture Theatre, Whitby",
};

/** The booking fee for each seat, in dollars. */
export const SEAT_FEE = 1.5;
/** How many seats one booking may hold. */
export const MAX_SEATS = 6;
/** How long a hold lasts, in seconds. */
export const HOLD_SECONDS = 600;

/** The map's drawing box: where it starts and how big it is, in map units. */
export const VIEW = { x: 120, y: 24, width: 760, height: 460 };
/** The point the rows curve around, just above the stage. */
export const HUB = { x: 500, y: 20 };

const ROWS = 12;
const FIRST_RADIUS = 140;
const ROW_GAP = 26;
const SEAT_GAP = 22;
const DEGREE = Math.PI / 180;
const SECTIONS: { section: Section; from: number; to: number }[] = [
  { section: "left", from: -55 * DEGREE, to: -18.5 * DEGREE },
  { section: "centre", from: -15.5 * DEGREE, to: 15.5 * DEGREE },
  { section: "right", from: 18.5 * DEGREE, to: 55 * DEGREE },
];

function tierFor(section: Section, row: number): TierId {
  if (row >= 8) return "upper";
  if (section !== "centre") return "side";
  return row < 4 ? "front" : "middle";
}

/** Builds every seat of the hall, the same way on the server and in the browser. */
function buildSeats(): Seat[] {
  const random = seededRandom(91);
  const seats: Seat[] = [];
  for (let row = 0; row < ROWS; row += 1) {
    const radius = FIRST_RADIUS + row * ROW_GAP;
    const rowName = String.fromCharCode(65 + row);
    let number = 0;
    for (const { section, from, to } of SECTIONS) {
      // Seats sit 22 units apart along the arc, centred in their block.
      const count = Math.floor(((to - from) * radius) / SEAT_GAP) + 1;
      const spread = ((count - 1) * SEAT_GAP) / radius;
      const start = (from + to) / 2 - spread / 2;
      for (let place = 0; place < count; place += 1) {
        number += 1;
        const angle = count === 1 ? (from + to) / 2 : start + (place * spread) / (count - 1);
        const wheelchair = row === 7 && section === "centre" && (place < 2 || place >= count - 2);
        const roll = random();
        seats.push({
          id: `${rowName}${number}`,
          row,
          rowName,
          number,
          section,
          tier: tierFor(section, row),
          status: wheelchair ? "open" : roll < 0.3 ? "sold" : roll < 0.36 ? "held" : "open",
          wheelchair,
          // Rounded so the server and the browser print the same number and hydration matches.
          x: Math.round((HUB.x + Math.sin(angle) * radius) * 100) / 100,
          y: Math.round((HUB.y + Math.cos(angle) * radius) * 100) / 100,
          angle,
        });
      }
    }
  }
  return seats;
}

/** Every seat in the hall, row by row from the stage, left to right in each row. */
export const SEATS = buildSeats();

/** The seat the arrow keys reach from `seat`, or the same seat at an edge. */
export function neighbour(seats: Seat[], seat: Seat, key: string): Seat {
  if (key === "ArrowLeft" || key === "ArrowRight") {
    const row = seats.filter((item) => item.row === seat.row);
    const at = row.findIndex((item) => item.id === seat.id);
    return row[at + (key === "ArrowLeft" ? -1 : 1)] ?? seat;
  }
  const target = seat.row + (key === "ArrowUp" ? -1 : 1);
  const row = seats.filter((item) => item.row === target);
  let best: Seat = seat;
  let gap = Number.POSITIVE_INFINITY;
  for (const item of row) {
    const distance = Math.abs(item.angle - seat.angle);
    if (distance < gap) {
      gap = distance;
      best = item;
    }
  }
  return best;
}

/** The label a screen reader hears for one seat. */
/** Where a seat is, such as "Row C, seat 12". */
export function seatPlace(seat: Seat): string {
  return seat.wheelchair ? `Row ${seat.rowName}, wheelchair space ${seat.number}` : `Row ${seat.rowName}, seat ${seat.number}`;
}

export function seatLabel(seat: Seat, chosen: boolean): string {
  const tier = TIERS.find((item) => item.id === seat.tier);
  const place = seatPlace(seat);
  const state = seat.status === "sold" ? "sold" : seat.status === "held" ? "on hold for someone else" : chosen ? "chosen" : "open";
  return `${place}, ${tier?.name ?? ""}, $${tier?.price ?? 0}, ${state}`;
}

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import { motion } from "motion/react";
import { type KeyboardEvent, type PointerEvent, useRef, useState } from "react";

import { cn } from "@/lib/utils";

import { HUB, neighbour, type Seat, seatLabel, seatPlace, type TierId, TIERS, VIEW } from "./data";
import type { Camera } from "./use-camera";

/** Props for the hall map. */
export interface HallMapProps {
  seats: Seat[];
  chosen: ReadonlySet<string>;
  /** The seat that holds the map's one tab stop. */
  focusId: string;
  onFocusSeat: (seat: Seat) => void;
  onToggle: (seat: Seat) => void;
  /** A chosen tier dims every other tier's seats. */
  activeTier: TierId | null;
  camera: Camera;
}

const FILL = Object.fromEntries(TIERS.map((tier) => [tier.id, tier.fill]));
// A press that travels further than this, in screen pixels, is a drag and never picks a seat.
const DRAG_SLOP = 5;

function arc(radius: number, from: number, to: number) {
  const point = (angle: number) => `${HUB.x + Math.sin(angle) * radius} ${HUB.y + Math.cos(angle) * radius}`;
  return { start: point(from), end: point(to) };
}

/** The stage as a curved band in front of the first row. */
function stagePath() {
  const spread = (42 * Math.PI) / 180;
  const outer = arc(108, spread, -spread);
  const inner = arc(52, -spread, spread);
  return `M ${outer.start} A 108 108 0 0 1 ${outer.end} L ${inner.start} A 52 52 0 0 0 ${inner.end} Z`;
}

/**
 * The hall seen from above: the stage, three blocks of curved rows, and a
 * seat for every place. The map is one tab stop that lands on one seat; the
 * arrows move along the row or toward and away from the stage, and Enter or
 * Space picks the seat. A drag pans the camera and never picks a seat.
 */
export function HallMap({ seats, chosen, focusId, onFocusSeat, onToggle, activeTier, camera }: HallMapProps) {
  const svg = useRef<SVGSVGElement>(null);
  const press = useRef<{ x: number; y: number; lookX: number; lookY: number; zoom: number; dragged: boolean } | null>(null);
  const dragged = useRef(false);
  // The seat under the pointer, or else the one keyboard focus is on, which the tag above it names.
  const [hovered, setHovered] = useState<Seat | null>(null);
  const [focused, setFocused] = useState<Seat | null>(null);
  const tagged = hovered ?? focused;

  const focusSeat = (seat: Seat) => {
    onFocusSeat(seat);
    const element = svg.current?.querySelector<SVGElement>(`[data-seat="${seat.id}"]`);
    element?.focus();
  };

  const onPointerDown = (event: PointerEvent<SVGSVGElement>) => {
    const look = camera.read();
    press.current = { x: event.clientX, y: event.clientY, lookX: look.x, lookY: look.y, zoom: look.zoom, dragged: false };
    dragged.current = false;
  };

  const onPointerMove = (event: PointerEvent<SVGSVGElement>) => {
    const start = press.current;
    const box = svg.current?.getBoundingClientRect();
    if (!start || !box || box.width === 0) return;
    const dx = event.clientX - start.x;
    const dy = event.clientY - start.y;
    if (!start.dragged && Math.hypot(dx, dy) < DRAG_SLOP) return;
    if (!start.dragged) {
      start.dragged = true;
      dragged.current = true;
      // Capture only once the press is a drag, so a plain tap still reaches the seat under it.
      event.currentTarget.setPointerCapture(event.pointerId);
    }
    const unitsPerPixel = VIEW.width / box.width / start.zoom;
    camera.panTo(start.lookX - dx * unitsPerPixel, start.lookY - dy * unitsPerPixel);
  };

  const endPress = () => {
    press.current = null;
  };

  return (
    <motion.svg
      ref={svg}
      viewBox={camera.viewBox}
      role="group"
      aria-label="Hall map. Use the arrow keys to move between seats, and Enter or Space to choose one."
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endPress}
      onPointerCancel={endPress}
      className={cn("block h-auto w-full cursor-grab select-none active:cursor-grabbing", camera.zoom > 1.01 ? "touch-none" : "touch-pan-y")}
    >
      <g>
        <path d={stagePath()} className="fill-muted stroke-border" strokeWidth="1" />
        <text x={HUB.x} y={HUB.y + 88} textAnchor="middle" className="fill-muted-foreground text-xs font-medium">
          Stage
        </text>
        {[
          { label: "Left", x: 237, y: 376 },
          { label: "Centre", x: 500, y: 478 },
          { label: "Right", x: 763, y: 376 },
        ].map((item) => (
          <text key={item.label} aria-hidden="true" x={item.x} y={item.y} textAnchor="middle" className="fill-muted-foreground text-xs">
            {item.label}
          </text>
        ))}
        {seats.map((seat) => {
          const isChosen = chosen.has(seat.id);
          const dim = activeTier !== null && seat.tier !== activeTier;
          const shared = {
            "data-seat": seat.id,
            role: "checkbox",
            "aria-checked": isChosen,
            "aria-disabled": seat.status !== "open",
            "aria-label": seatLabel(seat, isChosen),
            tabIndex: seat.id === focusId ? 0 : -1,
            strokeWidth: 3,
            onFocus: () => {
              onFocusSeat(seat);
              setFocused(seat);
              // Focus moving to a seat names that seat, even while the pointer rests on another.
              setHovered(null);
            },
            onBlur: () => setFocused((current) => (current?.id === seat.id ? null : current)),
            onPointerEnter: () => setHovered(seat),
            onPointerLeave: () => setHovered((current) => (current?.id === seat.id ? null : current)),
            onClick: () => {
              if (dragged.current) return;
              onFocusSeat(seat);
              onToggle(seat);
            },
            onKeyDown: (event: KeyboardEvent<SVGElement>) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault();
                onToggle(seat);
              } else if (event.key.startsWith("Arrow")) {
                event.preventDefault();
                focusSeat(neighbour(seats, seat, event.key));
              }
            },
            className: cn(
              "cursor-pointer stroke-transparent outline-none focus-visible:stroke-foreground motion-safe:transition-opacity",
              seat.status !== "open" && "cursor-not-allowed",
              dim && "opacity-25",
              isChosen
                ? "fill-foreground"
                : seat.status === "sold"
                  ? "fill-border"
                  : seat.status === "held"
                    ? "fill-card stroke-muted-foreground focus-visible:stroke-foreground"
                    : cn(FILL[seat.tier], "hover:stroke-foreground"),
            ),
          };
          return seat.wheelchair ? (
            <rect key={seat.id} x={seat.x - 7} y={seat.y - 7} width="14" height="14" rx="3.5" {...shared} />
          ) : (
            <circle key={seat.id} cx={seat.x} cy={seat.y} r={seat.status === "sold" ? 5 : 7.5} {...shared} />
          );
        })}
        {seats
          .filter((seat) => chosen.has(seat.id))
          .map((seat) => (
            <path
              key={`${seat.id}-tick`}
              aria-hidden="true"
              d={`M ${seat.x - 3.2} ${seat.y + 0.2} l 2.2 2.2 l 4.2 -4.6`}
              fill="none"
              className="pointer-events-none stroke-background"
              strokeWidth="1.8"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          ))}
        {tagged ? <SeatTag seat={tagged} bounds={visibleSpan(camera)} /> : null}
      </g>
    </motion.svg>
  );
}

/** A small tag above the hovered seat that names its row, number and price. Screen readers hear the seat's own label instead. */
/** The left and right edges of the part of the hall in view, in map units. */
interface VisibleSpan {
  left: number;
  right: number;
}

function visibleSpan(camera: Camera): VisibleSpan {
  const look = camera.read();
  const half = VIEW.width / look.zoom / 2;
  return { left: look.x - half, right: look.x + half };
}

function SeatTag({ seat, bounds }: { seat: Seat; bounds: VisibleSpan }) {
  const tier = TIERS.find((item) => item.id === seat.tier);
  const state = seat.status === "open" ? `$${tier?.price ?? 0}` : seat.status === "sold" ? "sold" : "on hold";
  const text = `${seatPlace(seat)}, ${state}`;
  // SVG cannot size a box to its text, so the width follows the character count at the tag's type size.
  const width = text.length * 6.4 + 20;
  // Centred on the seat, but held inside the part of the hall in view so an outer seat's tag is never cut.
  const x = Math.min(Math.max(seat.x, bounds.left + width / 2), bounds.right - width / 2);
  return (
    <g aria-hidden="true" className="pointer-events-none" transform={`translate(${x} ${seat.y - 16})`}>
      <rect x={-width / 2} y={-26} width={width} height={22} rx={6} className="fill-popover stroke-border" strokeWidth={1} />
      <text y={-11} textAnchor="middle" className="fill-popover-foreground text-xs font-medium">
        {text}
      </text>
    </g>
  );
}

"use client";

import { animate, type MotionValue, useMotionValue, useReducedMotion, useTransform } from "motion/react";
import { useCallback, useState } from "react";

import { VIEW } from "./data";

/** Where the camera looks and how close it is. */
export interface CameraTarget {
  x: number;
  y: number;
  zoom: number;
}

/** The map's camera: an SVG view box that follows one spring, and the moves that drive it. */
export interface Camera {
  /** The `viewBox` attribute for the map's SVG: the part of the hall in view. */
  viewBox: MotionValue<string>;
  /** The zoom the camera is heading to, for the zoom buttons and the touch rule. */
  zoom: number;
  /** Glides to a point and zoom. A drag or another move takes over mid-flight. */
  flyTo: (target: CameraTarget) => void;
  /** Moves the view by a distance in map units, with no spring, as a drag does. */
  panTo: (x: number, y: number) => void;
  /** Where the camera looks now, for a drag that starts mid-flight. */
  read: () => CameraTarget;
}

/** The closest the camera gets. */
export const MAX_ZOOM = 3.2;

const CENTRE = { x: VIEW.x + VIEW.width / 2, y: VIEW.y + VIEW.height / 2 };
// Critically damped: damping is 2 times the square root of stiffness times mass, so the camera lands with no overshoot.
const STIFFNESS = 140;
const GLIDE = { type: "spring" as const, stiffness: STIFFNESS, damping: 2 * Math.sqrt(STIFFNESS), mass: 1 };

/** Keeps the look point inside the map, so a pan never shows only empty space. */
function clampTarget({ x, y, zoom }: CameraTarget): CameraTarget {
  const z = Math.min(MAX_ZOOM, Math.max(1, zoom));
  const halfWidth = VIEW.width / 2 / z;
  const halfHeight = VIEW.height / 2 / z;
  return {
    zoom: z,
    x: Math.min(VIEW.x + VIEW.width - halfWidth, Math.max(VIEW.x + halfWidth, x)),
    y: Math.min(VIEW.y + VIEW.height - halfHeight, Math.max(VIEW.y + halfHeight, y)),
  };
}

/**
 * Drives the seat map's camera. Every move runs on one critically damped
 * spring per axis, so zooming, flying to a tier and following the keyboard
 * glide without overshoot. With reduced motion every move is instant.
 */
export function useCamera(): Camera {
  const reduceMotion = useReducedMotion();
  const x = useMotionValue(CENTRE.x);
  const y = useMotionValue(CENTRE.y);
  const zoom = useMotionValue(1);
  const [zoomTarget, setZoomTarget] = useState(1);
  const viewBox = useTransform([x, y, zoom], ([lookX = CENTRE.x, lookY = CENTRE.y, scale = 1]: number[]) => {
    const width = VIEW.width / scale;
    const height = VIEW.height / scale;
    return `${lookX - width / 2} ${lookY - height / 2} ${width} ${height}`;
  });

  const flyTo = useCallback(
    (target: CameraTarget) => {
      const next = clampTarget(target);
      setZoomTarget(next.zoom);
      if (reduceMotion) {
        x.jump(next.x);
        y.jump(next.y);
        zoom.jump(next.zoom);
        return;
      }
      animate(x, next.x, GLIDE);
      animate(y, next.y, GLIDE);
      animate(zoom, next.zoom, GLIDE);
    },
    [reduceMotion, x, y, zoom],
  );

  const panTo = useCallback(
    (nextX: number, nextY: number) => {
      x.stop();
      y.stop();
      const next = clampTarget({ x: nextX, y: nextY, zoom: zoom.get() });
      x.set(next.x);
      y.set(next.y);
    },
    [x, y, zoom],
  );

  const read = useCallback(() => ({ x: x.get(), y: y.get(), zoom: zoom.get() }), [x, y, zoom]);

  return { viewBox, zoom: zoomTarget, flyTo, panTo, read };
}

/** The camera that shows the whole hall. */
export const WHOLE_HALL: CameraTarget = { ...CENTRE, zoom: 1 };

