/** Props for the summary of the chosen seats. */
export interface SeatSummaryProps {
  seats: Seat[];
  /** Seconds left on the hold, or null when nothing is held. */
  secondsLeft: number | null;
  /** The last thing that happened, read to screen readers. */
  message: string;
  onRemove: (seat: Seat) => void;
  onBook: () => void;
