const clock = (seconds: number) => `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
const priceOf = (seat: Seat) => TIERS.find((tier) => tier.id === seat.tier)?.price ?? 0;

/**
 * The chosen seats with their prices, the booking fee, the total and the hold
 * countdown. Each seat can be let go from here. The countdown is a timer, so
 * a screen reader does not hear every second; the message line says when the
 * hold runs out.
 */
export function SeatSummary({ seats, secondsLeft, message, onRemove, onBook }: SeatSummaryProps) {
  const reduceMotion = useReducedMotion();
  const subtotal = seats.reduce((sum, seat) => sum + priceOf(seat), 0);
  const fees = seats.length * SEAT_FEE;
  const urgent = secondsLeft !== null && secondsLeft <= 60;

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
