        {secondsLeft !== null ? (
          <span role="timer" className={`flex items-center gap-1.5 text-sm tabular-nums ${urgent ? STATUS_TEXT.bad : "text-muted-foreground"}`}>
            <ClockIcon aria-hidden="true" className="size-4" />
            Held for {clock(secondsLeft)}
          </span>
        ) : null}
      </div>

      {seats.length === 0 ? (
        <p className="text-sm text-muted-foreground">Choose up to six seats on the map. We hold them for ten minutes while you book.</p>
      ) : (
        <ul className="flex flex-col">
          <AnimatePresence initial={false}>
            {seats.map((seat) => (
              <motion.li
                key={seat.id}
                initial={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                animate={reduceMotion ? { opacity: 1 } : { opacity: 1, height: "auto" }}
                exit={reduceMotion ? { opacity: 0 } : { opacity: 0, height: 0 }}
                transition={{ duration: 0.2 }}
                className="overflow-hidden"
              >
                <div className="flex items-center justify-between gap-3 border-b border-border py-1.5 text-sm">
                  <span>
                    Row {seat.rowName}, {seat.wheelchair ? "wheelchair space" : "seat"} {seat.number}
                    <span className="text-muted-foreground">, {TIERS.find((tier) => tier.id === seat.tier)?.name}</span>
                  </span>
                  <span className="flex items-center gap-1">
                    <span className="tabular-nums">{formatCents(priceOf(seat))}</span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      aria-label={`Let go of row ${seat.rowName}, seat ${seat.number}`}
                      onClick={() => onRemove(seat)}
                      className="size-7"
                    >
                      <XIcon aria-hidden="true" className="size-3.5" />
                    </Button>
                  </span>
                </div>
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      )}

      <dl className="flex flex-col gap-1 text-sm">
        <div className="flex justify-between">
          <dt className="text-muted-foreground">Booking fee, {formatCents(SEAT_FEE)} a seat</dt>
          <dd>
            <RollingText text={formatCents(fees)} />
          </dd>
        </div>
        <div className="flex items-baseline justify-between">
          <dt className="font-medium">Total</dt>
          <dd>
            <RollingText text={formatCents(subtotal + fees)} className="text-lg font-semibold" />
          </dd>
        </div>
      </dl>
      <p role="status" className="min-h-5 text-sm text-muted-foreground">
        {message}
      </p>
      <Button type="button" disabled={seats.length === 0} onClick={onBook}>
        {seats.length === 0 ? "Choose a seat to book" : `Book ${seats.length} ${seats.length === 1 ? "seat" : "seats"}`}
      </Button>
    </div>
  );
}

/** The three states a figure or a row can be in. */
export type Status = "good" | "watch" | "bad";

/** The text colour for each state. Each one passes 4.5 to 1 on a card in both themes. */
export const STATUS_TEXT = {
  good: "text-marketing-green-ink",
  watch: "text-marketing-amber-ink",
  bad: "text-marketing-orange-ink",
} satisfies Record<Status, string>;

/** A tinted surface for each state, for a pill or a cell. Pair it with the matching text colour. */
export const STATUS_SURFACE = {
  good: "bg-marketing-green-surface",
  watch: "bg-marketing-amber-surface",
  bad: "bg-marketing-orange-surface",
} satisfies Record<Status, string>;

/** The word a screen reader and a label use for each state. Colour never carries a state alone. */
export const STATUS_WORD = {
  good: "Good",
  watch: "Watch",
  bad: "At risk",
} satisfies Record<Status, string>;

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

const CENTS = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2, maximumFractionDigits: 2 });
const WHOLE = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A dollar amount with cents, such as $1,240.50. */
export const formatCents = (value: number) => CENTS.format(value);

/** A dollar amount rounded to whole dollars, such as $48. */
export const formatDollars = (value: number) => WHOLE.format(Math.round(value));

/** A signed dollar amount with cents, such as +$120.00 or −$48.20, for a ledger row. */
export const formatSigned = (value: number) => `${value < 0 ? "−" : "+"}${CENTS.format(Math.abs(value))}`;

/** Rounds to whole cents, so totals add up the way an invoice prints them. */
export const roundCents = (value: number) => Math.round(value * 100) / 100;

"use client";

import { Button } from "@/components/ui/button";
