import { formatDollars } from "../money";
import { type Seat, type TierId, TIERS } from "./data";

/** Props for the price tier chips. */
export interface TierChipsProps {
  seats: Seat[];
  /** Seats the person has chosen, which no longer count as left. */
  chosen: ReadonlySet<string>;
  active: TierId | null;
  onChange: (tier: TierId | null) => void;
}

/**
 * One chip per price tier with its price and how many seats are left. A chip
 * is a toggle: pressing it shows only that tier's seats at full colour and
 * flies the map to them; pressing it again shows the whole hall.
 */
export function TierChips({ seats, chosen, active, onChange }: TierChipsProps) {
  return (
    <div role="group" aria-label="Price tiers" className="scroll-fade-effect-x scrollbar-none flex gap-2 overflow-x-auto px-5 py-3">
      {TIERS.map((tier) => {
        const left = seats.filter((seat) => seat.tier === tier.id && seat.status === "open" && !chosen.has(seat.id)).length;
        const on = active === tier.id;
        return (
          <Button
            key={tier.id}
            type="button"
            variant={on ? "secondary" : "outline"}
            size="sm"
            aria-pressed={on}
            onClick={() => onChange(on ? null : tier.id)}
            className="shrink-0"
          >
            <span aria-hidden="true" className={cn("size-2.5 rounded-full", tier.dot)} />
            {tier.name}
            <span className="font-normal">{formatDollars(tier.price)}</span>
            <span className="font-normal text-muted-foreground">{left} left</span>
          </Button>
        );
      })}
    </div>
  );
}
